from PIL import Image, ImageFilter
import numpy as np

def enhance(img):
    blur = img.filter(ImageFilter.GaussianBlur(18))
    a = np.array(img).astype(np.float32); b = np.array(blur).astype(np.float32)
    return Image.fromarray(np.clip(b*0.75 + (a-b)*2.6 + 25, 0, 255).astype(np.uint8))

base = Image.open('radiograph.jpg').convert('L')
regions = {
 'zA': (590, 860, 790, 1000),    # tooth A apices
 'zB': (1540, 860, 1740, 1010),  # tooth B mesial+distal apices
 'zC': (620, 450, 920, 640),     # upper right molar apices
 'zD': (1400, 450, 1700, 640),   # upper left molar apices
}
for name,(x1,y1,x2,y2) in regions.items():
    c = enhance(base.crop((x1,y1,x2,y2)))
    c = c.resize((c.width*5, c.height*5), Image.LANCZOS)
    c.save(f'crops/{name}.png')
    print(name, c.size)
EOF", "description": "Generate 5x enhanced crops of apex regions"}

